import re

_VERSION_RE = re.compile(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$')
_COMPARATOR_RE = re.compile(r'^(>=|<=|>|<|=)?\s*(.*)$')


def satisfies(version: str, spec: str) -> bool:
    """Return True if `version` satisfies `spec`.

    Supported specs: exact ('1.2.3'), caret ('^1.2.3'), tilde ('~1.2.3'),
    or a space-separated conjunction of comparators ('>=1.0.0 <2.0.0').
    Raises ValueError on malformed input.
    """

    def parse_version(text):
        if not isinstance(text, str):
            raise ValueError("version must be a string")
        m = _VERSION_RE.match(text.strip())
        if not m:
            raise ValueError("malformed version: %r" % (text,))
        return tuple(int(g) for g in m.groups())

    ver = parse_version(version)

    if not isinstance(spec, str):
        raise ValueError("spec must be a string")
    s = spec.strip()
    if not s:
        raise ValueError("empty spec")

    def in_range(low, high):  # [low, high)
        return low <= ver < high

    # Caret / tilde ranges: must constitute the whole spec.
    if s[0] in '^~':
        base = parse_version(s[1:])
        M, m, p = base
        if s[0] == '^':
            if M > 0:
                upper = (M + 1, 0, 0)
            elif m > 0:
                upper = (0, m + 1, 0)
            else:
                upper = (0, 0, p + 1)
        else:  # '~'
            upper = (M, m + 1, 0)
        return in_range(base, upper)

    # Otherwise: conjunction of comparators (or a bare exact version).
    raw_tokens = s.split()
    tokens = []
    i = 0
    while i < len(raw_tokens):
        tok = raw_tokens[i]
        if tok in ('>=', '<=', '>', '<', '='):
            # operator separated from its version by whitespace
            if i + 1 >= len(raw_tokens):
                raise ValueError("malformed spec: %r" % (spec,))
            tokens.append(tok + raw_tokens[i + 1])
            i += 2
        else:
            tokens.append(tok)
            i += 1

    if not tokens:
        raise ValueError("malformed spec: %r" % (spec,))

    for tok in tokens:
        if tok[0] in '^~':
            raise ValueError("caret/tilde ranges cannot be combined: %r" % (spec,))
        m = _COMPARATOR_RE.match(tok)
        op = m.group(1) or '='
        target = parse_version(m.group(2))
        if op == '=':
            ok = ver == target
        elif op == '>':
            ok = ver > target
        elif op == '>=':
            ok = ver >= target
        elif op == '<':
            ok = ver < target
        else:  # '<='
            ok = ver <= target
        if not ok:
            return False
    return True
```

Notes: versions must be exactly three non-negative integers without leading zeros (per semver); anything else raises `ValueError`. Caret/tilde ranges are only valid as a complete spec, while comparators may be freely conjoined (a bare version inside a conjunction is treated as `=`).
